self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.pathname.startsWith(BASE))return;if(URLS.includes(url.pathname)){event.respondWith(caches.open(CACHE).then(async cache=>(await cache.match(url.pathname,{ignoreVary:true}))||fetch(event.request)));return;}if(event.request.mode==='navigate'&&!/\.[a-z0-9]+$/i.test(url.pathname)){event.respondWith(caches.open(CACHE).then(async cache=>(await cache.match(BASE+'index.html',{ignoreVary:true}))||fetch(event.request)));}});
